ST.xhtml:
(* Na primeira chamada, preenche o buffer para evitar transitorio *)
IF NOT bInit THEN
    FOR i := 0 TO GVL_Main.C_FILTER_SIZE - 1 DO
        aBuf[i] := rIn;
    END_FOR;
    bInit := TRUE;
END_IF;

(* Buffer circular *)
aBuf[iIdx] := rIn;
iIdx := iIdx + 1;
IF iIdx > GVL_Main.C_FILTER_SIZE - 1 THEN
    iIdx := 0;
END_IF;

(* Soma e media *)
rSum := 0.0;
FOR i := 0 TO GVL_Main.C_FILTER_SIZE - 1 DO
    rSum := rSum + aBuf[i];
END_FOR;
rOut := rSum / INT_TO_REAL(GVL_Main.C_FILTER_SIZE);

(* Histerese: a saida mantem o ultimo estado entre os limites *)
IF NOT bEnable THEN
    bFillValve := FALSE;
ELSIF rLevel_pct <= rLowOn_pct THEN
    bFillValve := TRUE;
ELSIF rLevel_pct >= rHighOff_pct THEN
    bFillValve := FALSE;
END_IF;

(* Permissivo de envase e alarme de nivel baixo *)
bTankOk        := rLevel_pct >= rMinOperate_pct;
bLowLevelAlarm := NOT bTankOk;

(* ---- 1. Temporizadores e deteccao de borda ---- *)
bWatchBottle := (eState = E_LineState.CLAMPING) OR (eState = E_LineState.FILLING)
                OR (eState = E_LineState.DRIPPING);

trigReset(CLK := bReset);
tonClamp  (IN := (eState = E_LineState.CLAMPING)   AND NOT bClampClosed, PT := GVL_Main.C_T_CYL_TIMEOUT);
tonTare   (IN := (eState = E_LineState.CLAMPING)   AND bClampClosed,     PT := GVL_Main.C_T_TARE);
tonUnclamp(IN := (eState = E_LineState.UNCLAMPING) AND NOT bClampOpen,   PT := GVL_Main.C_T_CYL_TIMEOUT);
tonFill   (IN := (eState = E_LineState.FILLING),                         PT := stRecipe.tFillTimeout);
tonDrip   (IN := (eState = E_LineState.DRIPPING),                        PT := stRecipe.tDrip);
tonBottle (IN := bWatchBottle AND NOT bBottlePresent,                    PT := GVL_Main.C_T_BOTTLE_DEB);

(* ---- 2. Deteccao de falhas (seguranca tem a maior prioridade) ---- *)
eFaultNew := E_Fault.NONE;
IF NOT bSafetyOk THEN
    eFaultNew := E_Fault.SAFETY;
ELSIF tonClamp.Q THEN
    eFaultNew := E_Fault.CLAMP_TIMEOUT;
ELSIF tonUnclamp.Q THEN
    eFaultNew := E_Fault.UNCLAMP_TIMEOUT;
ELSIF tonFill.Q THEN
    eFaultNew := E_Fault.FILL_TIMEOUT;
ELSIF tonBottle.Q THEN
    eFaultNew := E_Fault.BOTTLE_REMOVED;
END_IF;

IF (eFaultNew <> E_Fault.NONE) AND (eState <> E_LineState.FAULT)
   AND (eState <> E_LineState.DISABLED) THEN
    IF bInProcess THEN
        diRejected     := diRejected + 1;     (* Garrafa abortada = rejeitada *)
        bInProcess     := FALSE;
        bFaultMidCycle := TRUE;
    ELSE
        bFaultMidCycle := FALSE;
    END_IF;
    eFault := eFaultNew;
    eState := E_LineState.FAULT;
END_IF;

(* ---- 3. Massa liquida ---- *)
IF (eState = E_LineState.FILLING) OR (eState = E_LineState.DRIPPING) THEN
    rNetMass_g := rMass_g - rTare_g;
ELSIF eState = E_LineState.WAIT_BOTTLE THEN
    rNetMass_g := 0.0;
END_IF;

(* ---- 4. Maquina de estados ---- *)
CASE eState OF

    E_LineState.DISABLED:
        bClampCmd  := FALSE;
        bFillValve := FALSE;
        IF bEnable THEN
            eState := E_LineState.WAIT_BOTTLE;
        END_IF;

    E_LineState.WAIT_BOTTLE:
        bClampCmd  := FALSE;
        bFillValve := FALSE;
        IF NOT bEnable THEN
            eState := E_LineState.DISABLED;
        ELSIF bLotReady AND NOT bBottlePresent THEN
            eState := E_LineState.DONE;                  (* Posicao vazia: nada a envasar *)
        ELSIF bRun AND bLotReady AND bBottlePresent AND bTankOk THEN
            bInProcess := TRUE;
            eState     := E_LineState.CLAMPING;
        END_IF;

    E_LineState.CLAMPING:
        bClampCmd  := TRUE;
        bFillValve := FALSE;
        IF tonTare.Q THEN                                (* Cilindro fechado e massa estavel *)
            rTare_g := rMass_g;
            eState  := E_LineState.FILLING;
        END_IF;

    E_LineState.FILLING:
        bClampCmd := TRUE;
        IF rNetMass_g >= (stRecipe.rTargetMass_g - stRecipe.rPreAct_g) THEN
            bFillValve := FALSE;
            eState     := E_LineState.DRIPPING;
        ELSE
            bFillValve := TRUE;
        END_IF;

    E_LineState.DRIPPING:
        bClampCmd  := TRUE;
        bFillValve := FALSE;
        IF tonDrip.Q THEN
            IF ABS(rNetMass_g - stRecipe.rTargetMass_g) <= stRecipe.rTolerance_g THEN
                diFilled   := diFilled + 1;
            ELSE
                diRejected := diRejected + 1;
            END_IF;
            bInProcess := FALSE;
            eState     := E_LineState.UNCLAMPING;
        END_IF;

    E_LineState.UNCLAMPING:
        bClampCmd  := FALSE;
        bFillValve := FALSE;
        IF bClampOpen THEN
            eState := E_LineState.DONE;
        END_IF;

    E_LineState.DONE:
        bClampCmd  := FALSE;
        bFillValve := FALSE;
        IF NOT bLotReady THEN                            (* Lote saiu: prepara o proximo *)
            IF bEnable THEN
                eState := E_LineState.WAIT_BOTTLE;
            ELSE
                eState := E_LineState.DISABLED;
            END_IF;
        END_IF;

    E_LineState.FAULT:
        bClampCmd  := FALSE;                             (* Valvula fechada e garrafa liberada *)
        bFillValve := FALSE;
        IF trigReset.Q AND bSafetyOk THEN
            eFault := E_Fault.NONE;
            IF bFaultMidCycle THEN
                eState := E_LineState.DONE;              (* Garrafa ja contabilizada como rejeitada *)
            ELSE
                eState := E_LineState.WAIT_BOTTLE;
            END_IF;
            bFaultMidCycle := FALSE;
        END_IF;

END_CASE;

(* ---- 5. Saidas de status ---- *)
bFault    := (eState = E_LineState.FAULT);
bFinished := (eState = E_LineState.DISABLED) OR (eState = E_LineState.DONE);
bBusy     := (eState = E_LineState.CLAMPING) OR (eState = E_LineState.FILLING)
             OR (eState = E_LineState.DRIPPING) OR (eState = E_LineState.UNCLAMPING);

(* Zera os contadores de garrafas envasadas e rejeitadas da linha *)
diFilled   := 0;
diRejected := 0;

(* ---- 1. Seguranca: emergencia e porta (contatos NF) ---- *)
bSafetyOk := GVL_Main.bEStopOk AND GVL_Main.bGuardClosed;

(* ---- 2. Tanque pulmao com histerese ---- *)
GVL_Main.rTankLevel_pct := FC_Scale(iRaw    := GVL_Main.iTankLevelRaw,
                                    iRawMin := GVL_Main.C_RAW_MIN,
                                    iRawMax := GVL_Main.C_RAW_MAX,
                                    rEngMin := 0.0,
                                    rEngMax := GVL_Main.rTankLevelMax_pct);
fbTank(bEnable         := bSafetyOk,
       rLevel_pct      := GVL_Main.rTankLevel_pct,
       rLowOn_pct      := GVL_Main.rTankLowOn_pct,
       rHighOff_pct    := GVL_Main.rTankHighOff_pct,
       rMinOperate_pct := GVL_Main.rTankMinOperate_pct);
GVL_Main.qTankInletValve := fbTank.bFillValve;

(* ---- 3. Selecao de receita: somente com a maquina parada e sem garrafa em processo ---- *)
GVL_Main.bRecipeLocked := GVL_Main.bRunning OR bAnyBusy;
IF NOT GVL_Main.bRecipeLocked
   AND (GVL_Main.iRecipeReq >= 1) AND (GVL_Main.iRecipeReq <= 3)
   AND (GVL_Main.iRecipeReq <> GVL_Main.iRecipeActive) THEN
    GVL_Main.stActiveRecipe := GVL_Main.aRecipes[GVL_Main.iRecipeReq];
    GVL_Main.iRecipeActive  := GVL_Main.iRecipeReq;
END_IF;

(* ---- 4. Linhas de enchimento ---- *)
bAllFinished  := TRUE;
bAnyFault     := FALSE;
bAnyBusy      := FALSE;
diSumFilled   := 0;
diSumRejected := 0;

FOR i := 1 TO GVL_Main.C_NUM_LINES DO

    (* Escalonamento e media movel da celula de carga *)
    aLoadAvg[i](rIn := FC_Scale(iRaw    := GVL_Main.aiLoadCellRaw[i],
                                iRawMin := GVL_Main.C_RAW_MIN,
                                iRawMax := GVL_Main.C_RAW_MAX,
                                rEngMin := 0.0,
                                rEngMax := GVL_Main.rLoadCellFullScale_g));
    GVL_Main.arMassGross_g[i] := aLoadAvg[i].rOut;

    (* Ciclo da linha *)
    aLine[i](bEnable        := GVL_Main.abLineEnable[i],
             bSafetyOk      := bSafetyOk,
             bRun           := GVL_Main.bRunning,
             bLotReady      := (eConv = E_ConvState.PROCESSING),
             bTankOk        := fbTank.bTankOk,
             bBottlePresent := GVL_Main.abBottlePresent[i],
             bClampClosed   := GVL_Main.abClampClosed[i],
             bClampOpen     := GVL_Main.abClampOpen[i],
             bReset         := GVL_Main.bResetPB,
             rMass_g        := aLoadAvg[i].rOut,
             stRecipe       := GVL_Main.stActiveRecipe);

    (* Zeragem de contadores (pulso) *)
    IF GVL_Main.bClearCounters THEN
        aLine[i].M_ClearCounters();
    END_IF;

    (* Saidas fisicas e diagnostico *)
    GVL_Main.abClampCmd[i]  := aLine[i].bClampCmd;
    GVL_Main.abFillValve[i] := aLine[i].bFillValve;
    GVL_Main.arMassNet_g[i] := aLine[i].rNetMass_g;
    GVL_Main.aeLineState[i] := aLine[i].eState;
    GVL_Main.aeLineFault[i] := aLine[i].eFault;
    GVL_Main.adiFilled[i]   := aLine[i].diFilled;
    GVL_Main.adiRejected[i] := aLine[i].diRejected;

    (* Agregacao *)
    IF NOT aLine[i].bFinished THEN
        bAllFinished := FALSE;
    END_IF;
    IF aLine[i].bFault THEN
        bAnyFault := TRUE;
    END_IF;
    IF aLine[i].bBusy THEN
        bAnyBusy := TRUE;
    END_IF;
    diSumFilled   := diSumFilled   + aLine[i].diFilled;
    diSumRejected := diSumRejected + aLine[i].diRejected;

END_FOR;

GVL_Main.bClearCounters   := FALSE;
GVL_Main.diTotalFilled    := diSumFilled;
GVL_Main.diTotalRejected  := diSumRejected;

(* ---- 5. Liga/desliga da maquina ---- *)
trigStart(CLK := GVL_Main.bStartPB);
IF (NOT bSafetyOk) OR bAnyFault OR GVL_Main.bStopPB THEN
    GVL_Main.bRunning := FALSE;                          (* Emergencia/porta/falha/parada *)
ELSIF trigStart.Q AND (GVL_Main.iRecipeActive >= 1) THEN
    GVL_Main.bRunning := TRUE;
END_IF;

(* ---- 6. Sequenciamento da esteira ---- *)
trigLot(CLK := GVL_Main.bLotInPos);
tonSettle(IN := (eConv = E_ConvState.SETTLE) AND GVL_Main.bRunning,
          PT := GVL_Main.C_T_SETTLE);

CASE eConv OF

    E_ConvState.ADVANCE:
        (* Borda de subida do sensor = novo lote; na 1a partida aceita lote ja posicionado *)
        IF trigLot.Q
           OR (GVL_Main.bLotInPos AND NOT bConvStarted AND GVL_Main.bRunning) THEN
            eConv := E_ConvState.SETTLE;
        END_IF;

    E_ConvState.SETTLE:
        IF tonSettle.Q THEN
            eConv := E_ConvState.PROCESSING;
        END_IF;

    E_ConvState.PROCESSING:
        (* Todas as linhas habilitadas concluidas: avanca o proximo lote *)
        IF bAllFinished AND GVL_Main.bRunning THEN
            bConvStarted := TRUE;
            eConv        := E_ConvState.ADVANCE;
        END_IF;

END_CASE;

GVL_Main.qConveyor := GVL_Main.bRunning AND bSafetyOk AND (eConv = E_ConvState.ADVANCE);

(* ---- 7. Alarmes ---- *)
GVL_Main.bAlarmAny  := bAnyFault OR fbTank.bLowLevelAlarm;
GVL_Main.qAlarmLamp := GVL_Main.bAlarmAny;

(* Protecao contra divisao por zero *)
IF iRawMax = iRawMin THEN
    FC_Scale := rEngMin;
    RETURN;
END_IF;

(* Limita o bruto a faixa valida *)
rX := LIMIT(INT_TO_REAL(iRawMin), INT_TO_REAL(iRaw), INT_TO_REAL(iRawMax));

(* Interpolacao linear *)
FC_Scale := rEngMin + (rX - INT_TO_REAL(iRawMin)) * (rEngMax - rEngMin)
            / (INT_TO_REAL(iRawMax) - INT_TO_REAL(iRawMin));
